INSERT INTO `achievement_locale` (`ID`, `locale`, `Description_lang`, `Title_lang`, `Reward_lang`, `VerifiedBuild`) VALUES
(63325, 'koKR', '옴니움 장서에서 사용할 수 있는 총체적인 탐구의 티끌 5개 획득', '옴니움 장서 연구', '하우징 장식: 선스트라이더 옴니움 복제물', 68974),
(62903, 'koKR', '발 지역의 폭풍 소멸 5회', '이상 기후: 발', '애완동물: 생선 상인 키스 구매 가능', 68974),
(63343, 'koKR', '실버문에서 참여의 휘장을 착용한 상태로 차기 좋은 연습용 공을 사용해 득점', '득점!', '하우징 장식: 귀중한 아제로스의 보주, 호드의 자부심 액자, 얼라이언스의 자부심 액자', 68974),
(61336, 'koKR', '한밤에 있는 불꽃에 경의 표시하기', '한밤 불꽃감시자', '', 68974),
(61335, 'koKR', '한밤에 있는 불꽃에 경의 표시하기', '한밤 불꽃지기', '', 68974),
(61936, 'koKR', '공허첨탑에서 공격대원 전원이 최대 오라를 보유한 상태로 빛에 눈이 먼 선봉대 처치 (일반 난이도 이상)', '오라 비축', '', 68974),
(61911, 'koKR', '공허첨탑에서 모든 플레이어가 3초 안에 무위 지대의 사슬을 끊고 바엘고어와 에조라크 처치 (일반 난이도 이상)', '준비하시고, 끊으세요!', '', 68974),
(61514, 'koKR', '공허첨탑에서 전투 시작 전에 모두가 몰락한 왕 살라다르에게 /무릎 후 처치 (일반 난이도 이상)', '그게 바로 반역죄야', '', 68974),
(61381, 'koKR', '쿠엘다나스 진격로에서 태양샘 알에 빛과 공허 마법을 주입한 후 알라르의 자손 벨로렌 처치 (일반 난이도 이상)', '알의 위기', '', 68974),
(61346, 'koKR', '공허첨탑에서 살덩어리 괴수를 처치하고 모든 괴수의 고기를 텅 빈 공허에게 반환한 후 우주의 왕관 처치 (일반 난이도 이상)', '우리의 만남은 다시 한번', '', 68974),
(61611, 'koKR', '길드 파티로 쿠엘다나스 진격로에서 한밤의 도래 처치 (신화)', '신화: 한밤의 도래 길드 정복', '', 68974),
(61380, 'koKR', '아래 나열된 공격대 업적 완료', '영예의 한밤 공격대원', '탈것: 암영의 박해자', 68974),
(62874, 'koKR', '아래 나열된 업적 완료', '별을 가로지르는 모험가', '보상: 황천벼림 무위전투복 구매 가능', 68974);
INSERT INTO `adventure_journal_locale` (`ID`, `locale`, `Name_lang`, `Description_lang`, `ButtonText_lang`, `RewardDescription_lang`, `ContinueDescription_lang`, `VerifiedBuild`) VALUES
(909, 'koKR', '옴니움 장서 - 새로운 정보', '마법학자들이 옴니움 장서의 룬을 더욱더 강화할 실마리를 확보했다고 합니다.', '퀘스트 수락', '옴니움 장서의 또 다른 룬을 강화할 수 있는 총체적인 탐구의 티끌이 보상으로 증정됩니다.', '', 68974);
INSERT INTO `area_table_locale` (`ID`, `locale`, `AreaName_lang`, `VerifiedBuild`) VALUES
(15966, 'koKR', '프레닥사스의 소굴', 68974);
INSERT INTO `battle_pet_species_locale` (`ID`, `locale`, `Description_lang`, `SourceText_lang`, `VerifiedBuild`) VALUES
(4618, 'koKR', '휴식 모드: 활성화.\n안락 수준: 최대.\n내부 온도: 낮음.', '|cFFFFD200프로모션|r |n', 68974),
(4617, 'koKR', '주요 지령: 영웅적인 업적을 세울 것.\n선호하는 영웅적인 업적: 짜릿함.\n보조 지령: 영웅이 될 것.\n선호하는 영웅: 커다란 영웅.', '|cFFFFD200프로모션|r |n', 68974),
(4949, 'koKR', '아미드랏실을 타락시키려 했던 광염의 피락이 남긴 잔재입니다.', '|cFFFFD200상인: |r자이단|n|cFFFFD200지역: |r발드라켄|n|cFFFFD200가격: |r2200|Hcurrency:1166|h|TInterface\\ICONS\\PVECurrency-Justice.blp:0|t|h', 68974),
(5074, 'koKR', '사실 사일렌토는 공허폭풍에 사는 공허방랑자 중에서도 유독 별종으로 통합니다. 평화와 조용한 적막을 좋아하거든요. 말 많은 동족을 직접 침묵시킬 정도로 말입니다.', '|cFFFFD200업적:|r 결전 성공: 발 및 결전 성공: 나익탈|n|cFFFFD200상인: |r키판|n|cFFFFD200지역: |r발 또는 나익탈|n|cFFFFD200가격: |r15|Hcurrency:3316|h|TInterface\\ICONS\\INV_112_RaidTrinkets_VoidPrism.BLP:0|t|h', 68974),
(5073, 'koKR', '선조의 명성에 걸맞은 존재가 되기 위해, 이 작은 친구는 벌써 날뛸 준비를 마쳤습니다. 우선 작은 거미부터 시작하고, 차근차근 더 큰 사냥감을 상대할 생각이죠.', '|cFFFFD200업적:|r 울트라돈 학살|n|cFFFFD200상인: |r키판|n|cFFFFD200지역: |r발 또는 나익탈|n|cFFFFD200가격: |r15|Hcurrency:3316|h|TInterface\\ICONS\\INV_112_RaidTrinkets_VoidPrism.BLP:0|t|h', 68974),
(4898, 'koKR', '키스는 얼린 생선을 제일 좋아합니다. 즉, 얼린 생선이 있다면 새로운 절친을 사귈 수 있답니다.', '|cFFFFD200업적:|r 이상 기후: 발|n|cFFFFD200상인: |r키판|n|cFFFFD200지역: |r나익탈 또는 발|n|cFFFFD200가격: |r50|Hitem:238365|h|TInterface\\ICONS\\INV_Misc_Fish_41.blp:0|t|h |n|n', 68974);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(317639, 'koKR', '사령관 탈라산이 빛장막 망토를 벗고 앞으로 나섭니다.', '', 68974),
(314421, 'koKR', '아아악!', '', 68974),
(314420, 'koKR', '줄잔, 조심해!', '', 68974),
(314419, 'koKR', '하셰이도요!', '', 68974),
(314418, 'koKR', '이 힘만 있으면, 로아 따윈 필요 없습니다!', '', 68974),
(314417, 'koKR', '싫습니다!', '', 68974),
(314416, 'koKR', '어서 놓거라!', '', 68974),
(314415, 'koKR', '암흑 마법이다!', '', 68974),
(314414, 'koKR', '줄잔!', '', 68974),
(314413, 'koKR', '(신음)', '', 68974),
(314412, 'koKR', '이게 바로... 열쇠란 말이지...', '', 68974),
(314411, 'koKR', '찾았다!', '', 68974),
(314410, 'koKR', '아!', '', 68974),
(314408, 'koKR', '장담하마... 네 누이도 이해할 거다.', '', 68974),
(314407, 'koKR', '...울라텍의 힘을 쟁취해 돌아가면...', '', 68974),
(314406, 'koKR', '열쇠를 쥐어라, 줄잔.', '', 68974),
(314405, 'koKR', '누님이 숙부님을 보면...', '', 68974),
(314404, 'koKR', '이미 로아에게 완전히 휘둘리고 있는데...', '', 68974),
(314403, 'koKR', '누님은 어떻게 하지?', '', 68974),
(314402, 'koKR', '네 조부와 시작한 일을 끝낼 것이야.', '', 68974),
(314401, 'koKR', '로아의 공허한 약속에서 벗어나기 위해.', '', 68974),
(314400, 'koKR', '우리 종족의 미래를 지키고', '', 68974),
(314399, 'koKR', '그리고 네 도움이 필요하다.', '', 68974),
(314398, 'koKR', '말라크라스다.', '', 68974),
(314397, 'koKR', '그래...', '', 68974),
(314396, 'koKR', '그렇다면 넌...', '', 68974),
(314395, 'koKR', '네가 할아버지를 알아?', '', 68974),
(314394, 'koKR', '줄진과 난, 그런 운명을 바꾸려 했지...', '', 68974),
(314393, 'koKR', '애석하게도 이게 우리 종족의 운명이다.', '', 68974),
(314392, 'koKR', '...정작 마지막 숨을 거둘 때는 어디 있단 말인가?', '', 68974),
(314391, 'koKR', '평생을 로아에게 헌신했건만...', '', 68974),
(314390, 'koKR', '가슴 아프군.', '', 68974),
(314389, 'koKR', '안 돼, 안 된다고, 나는...', '', 68974),
(314388, 'koKR', '안 돼...', '', 68974),
(314387, 'koKR', '이미 죽었다, 줄잔.', '', 68974),
(314386, 'koKR', '숙부!', '', 68974),
(314385, 'koKR', '숙부?!', '', 68974),
(314384, 'koKR', '(기침)', '', 68974),
(310355, 'koKR', '그럼 전 돈스타 첨탑에서 사라진 부품을 찾아보겠습니다. 시간이 될 때 용사님도 합류해 주십시오. 롬매스, 행운을 빕니다.', '', 68974),
(317797, 'koKR', '<표정이 굳어지는 탈라산>\n\n제 많은 형제자매가... 절규가 울려 퍼지는 공허첨탑의 소용돌이에 휩쓸려 사라졌습니다.\n\n게다가 더 많은 이들이 몸뿐만 아니라 마음에도 깊은 상처를 입었습니다.\n\n첨탑에 진입한 많은 사람에게 무슨 일이 있었는지 압니다. $n 님은 직접 보셨지요? 분노... 혼란... 절망.\n\n우리는 이 전쟁에서 고결한 영혼을 너무 많이 잃었습니다. 파리야 님께 더 많은 병력을 내어 달라고 요구할 수는 없었습니다. 그분 역시 여력이 없었을 테니까요.', '', 68974),
(317795, 'koKR', '저는 빛의 군대 빛장막 부대의 사령관 탈라산입니다.\n\n균열칼날 마엘라의 요청에 따라 공허 세력과 할하다르를 추적하는 임무에 합류했습니다.\n\n저희는 이 적들과 적잖은 악연이 있습니다. 또, 미지의 영역으로 진입하는 일이라면 누구보다 적합한 병력이기도 합니다.\n\n여기 모인 이들은 빛장막 부대에서도 손꼽히는 정예입니다.', '', 68974),
(317659, 'koKR', '<룬 문자가 눈앞에서 일렁이다가 읽을 수 있는 문장으로 정돈됩니다.>\n\n빛행렬 임무 제어장치: 가동 중\n\n행성 명칭: 나익탈\n\n행성 위협 수준: 보통. \n \n지형 상황: 심각. 진입 시 주의 요망.\n\n현재 식별된 지형 내 위협: 할하다르\n...\n\n조회 항목을 선택하십시오.', '사령관 탈라산이 당신을 보고 고맙다는 듯 고개를 끄덕입니다.', 68974),
(317656, 'koKR', '', '툴아마르가 이를 악물고 잠시 입을 다뭅니다. 남은 한쪽 눈이 당신을 흘기더니, 다시 탈라산에게 향합니다.', 68974),
(317572, 'koKR', '나의, 아니, 우리의 새 장기말을 가까이서 눈여겨보겠다.', '', 68974),
(317571, 'koKR', '아직 우리의 일은 끝나지 않았다. 물론 임포투스가 앞길을 막을 걱정은 마라. 놈은 승리에 취해 성채에 틀어박힐 테니까.', '', 68974),
(317109, 'koKR', '이 얼어붙은 시궁창은 하찮다. 더 지배하기 쉽고, 더 알맞은 세계는 얼마든지 있어.', '', 68974),
(317012, 'koKR', '', '$n 님, 놈들이 찾아낼 것은 나샤보르를 터전으로 삼아 살아가는 드레나이들의 온전한 정착지입니다.\n\n나샤보르는 불타는 군단에 함락되지 않았습니다. 제네다르가 떠난 뒤 남은 이들도 기나긴 세월을 살아남았죠.\n\n할하다르가 아직 이 사실을 모른다 해도, 아제로스를 공격한 행태를 봤을 때 타인의 목숨을 얼마나 가볍게 여기는지는 자명합니다.\n\n나샤보르 주민들이 위험합니다.\n\n이 투영석을 툴아마르에게 가져다주시겠어요? 툴아마르도 알아야 할 일이니까요.', 68974),
(317008, 'koKR', '', '텔로루빌 역시 \"폐허\"로 여겨졌으니까요. 그런데도 놈들이 여기서 찾아낸 걸 보세요.\n\n할하다르 놈들이 이 행성은 물론이고, 제 동족이 나익탈에 이르기까지 방문한 모든 행성이 담긴 지도를 갖고 있다면 조만간 새로운 표적을 노릴 겁니다.\n\n감시자, 기술, 무덤, 폐허가 된 도시. 하나같이 약탈하기 좋은 사냥감으로밖에 안 보일 거예요.\n\n그런데 놈들이 나샤보르에서 버려진 폐허 대신 뭘 발견하게 될지 아세요?', 68974),
(317007, 'koKR', '', '용사님이 빌랄둔에서 싸운 감시자는 과거 아르거스에서 명망 높은 별예언가였습니다.\n\n영사관에서 키르살리아만큼 별을 깊이 아는 이는 드물었죠.\n\n투영석에 따르면, 키르살리아는 제네다르가 불타는 군단을 피해 도피하던 당시의 여정을 지도로 남겼습니다.\n\n키르살리아의 지도는 제네다르가 수많은 세계를 떠나 피신해 왔다는 증거이자, 뒤에 남겨진 이들을 떠올리게 하는 기록입니다.\n\n키르살리아의 항해도는 이곳 나익탈에 도착하면서 끝납니다. 텔로루빌이란 이름을 붙였더군요.\n\n그런데 이 항해도에 담긴 이름 중에 나샤보르 행성도 있더군요.\n\n키르살리아 역시 피난길에 오른 이들처럼, 나샤보르가 폐허가 되었으리라 생각한 거죠.', 68974),
(316762, 'koKR', '균열칼날 마엘라가 이번 원정에 동행해 달라고 요청했어요.\n\n베란은 공허와 할하다르를 잘 아니까, 이번 임무에 큰 도움이 될 거예요.\n\n저요? 글쎄요, 뭔가 뜯어 봐야 할 때 마도공학자가 필요할지도 모르잖아요!', '', 68974),
(316750, 'koKR', '', '안토러스 기록을 보면 발에 주둔한 군단의 규모는 극히 작았습니다. 이유야 뭐, 상상하기 어렵지 않네요.\n\n행성 대부분이 거대한 우박 폭풍에 뒤덮여 있습니다. 군단 함선의 선체도 찢어 버릴 정도지요.\n\n군단은 이 세계를 차지하려다 침공선을 최소 2척 잃었습니다.\n\n결국 몇몇 요새를 세우긴 했지만 모두 외딴 전초기지에 불과했죠.\n\n듣기로는 발의 전초기지에 배치되는 것 자체가 연이어 실패한 자들에게 내려지는 처벌이었다고 하더군요.', 68974),
(316562, 'koKR', '', '<일에 집중한 대마법사 이메라의 손이 잔상처럼 움직이며 제어장치에 룬 문자를 입력합니다.>\n\n공허 마력은 남쪽에 있는 성채에서 흘러나오고 있습니다. \n\n측정값을 보면 얼음 밑 아주 깊은 곳까지 이어져 있군요.', 68974),
(316520, 'koKR', '', '일리다리는 이 얼어붙은 지옥을 누구보다 잘 압니다. 군단은 이곳을 \"발\"이라 부르며 혹한의 환경을 포로 심문에 이용했습니다.\n\n차갑게 얼어붙은 죽음의 황무지라... 도마나르가 틀어박히기엔 딱 좋은 곳이군요.\n\n<데시무스를 노골적으로 곁눈질하는 마엘라>', 68974),
(316419, 'koKR', '<순간이동 신호기에는 목적지 단추가 두 개 있습니다. 하나는 실버문으로, 다른 하나는 공허폭풍으로 이어집니다. 한꺼번에 누르고 싶은 충동이 치밀어 오르지만, 참아야 합니다.>', '<순간이동 신호기에는 목적지 단추가 두 개 있습니다. 하나는 실버문으로, 다른 하나는 공허폭풍으로 이어집니다. 한꺼번에 누르고 싶은 충동이 치밀어 오르지만, 참아야 합니다.>', 68974),
(316274, 'koKR', '', '회수해 주신 홀로그램 출력물 덕분에 에테리얼이 드레나이 유물을 어디서 손에 넣고 있는지 알아냈습니다.\n\n섬 아래에 우리 종족이 세운 납골당이 있습니다.\n\n할하다르는 그 안의 수호자들은 물론이요, 편히 잠들지 못한 망자의 영혼까지 거둬들이고 있습니다.\n\n기록상으로는 무덤 내부에 감시자가 여럿 있으나, 아직 확보에는 실패한 듯합니다.\n\n운이 따른다면 놈들을 중간에서 끊어 낼 수 있을 겁니다.\n\n이번 납골당 진입은 탈라산 님이 지휘할 겁니다.', 68974),
(316214, 'koKR', '', '<수정 하나를 받아 들더니 눈이 휘둥그레지는 대마법사 이메라>\n\n$n 님, 여기 새겨진 룬은 드레나이식 룬입니다. 하기야 놀랄 일도 아니긴 하네요.\n\n기술에 관한 한 할하다르는 시체를 노리는 독수리나 다름없습니다. 발을 들인 세계의 폐허에서 쓸 만한 것은 모조리 긁어 가니까요.\n\n우리 기갑전투복을 찾아냈듯, 드레나이의 수정 기술도 어딘가에서 확보했을 겁니다.\n\n이 수정은 제가 살펴보겠습니다. 나머지는 키판에게 전달해 주세요. 키판은 지금 할하다르의 기술을 문서화하고 있습니다. \n\n이번 발견은 무역연합 마도공학자의 식견이 도움이 될 겁니다.', 68974),
(316212, 'koKR', '', '<일에 집중한 대마법사 이메라의 손이 잔상처럼 움직이며 제어장치에 룬 문자를 입력합니다.>\n\n운이 조금 따라줘서 해독이 잘 되면 할하다르가 이곳 나익탈에서 무엇을 노리는지 알아낼 수 있을 겁니다.\n\n용사님, 할하다르에 대해서는 아직 알아내야 할 것이 많습니다. \n\n이 기회를 놓쳐서는 안 됩니다.', 68974),
(314754, 'koKR', '적은 뒤에 있습니다. 돌아가야 합니다!', '적은 뒤에 있습니다. 돌아가야 합니다!', 68974),
(313932, 'koKR', '', '균열칼날 마엘라가 데시무스의 투영체를 맹렬하게 쏘아봅니다.', 68974),
(313749, 'koKR', '', '때가 됐나요? 균열칼날 마엘라가 보냈죠? 출발하기 전에 뭐 하나만 도와주세요!\n\n간단한 은신 주문과 계류선을 이용해 빛장막 기술을 손보고 있거든요.\n\n둘을 잘 합치면 도착하자마자 거점 전체를 숨길 수 있을 것 같아요.\n\n우선은 투명한 실험 대상이 하나 필요해요. 계류선의 거리 한계를 알아봐야 하거든요.\n\n좀 도와주시겠어요?', 68974),
(310380, 'koKR', '도마나르 전제군주 하나 쳐낸다고 필멸자 지도자를 처치했을 때처럼 지각 변동이 일어나진 않는다.', '', 68974),
(310377, 'koKR', '', '이제 페르티낙스는 골칫거리가 되지 않을 겁니다. 모두 용사님 덕분이죠.', 68974),
(310376, 'koKR', '그리고 놈들의 \"전제군주\"께서 친히 모습을 드러내거든... 이 황무지에서 치워주면 무척 고맙겠어.', '', 68974),
(310375, 'koKR', '', '이곳의 공허 세력을 꺾어 놓아야 고향에 있는 동족도 한숨 돌릴 수 있습니다. 용사님, 적을 교란해 주십시오.', 68974),
(310366, 'koKR', '빛... 지옥 마력... 공허. 긴장감을 고조시키기에 이 이상 좋은 조합도 없지. 군침이 도는군.', '', 68974),
(309048, 'koKR', '할하다르가 비행 소형선에 \"방어용\" 마력 포탑까지 달아 뒀다. 어디 얼마나 잘 막을지 한번 볼까?', '', 68974),
(309047, 'koKR', '저 \"할하다르\"에 대해 아는 건 별로 없지만, 어둠수호병보다는 훨씬 만만치 않은 상대 같군. 감당 못 할 지경이 되기 전에 수를 줄여 두는 게 좋겠어.', '', 68974),
(309020, 'koKR', '', '빛벼림 정찰대가 과거 이곳에 살았던 고대 공허 생명체의 흔적을 찾아냈습니다. 연구에 쓸 표본을 좀 채취해 주시겠어요?', 68974),
(309018, 'koKR', '너희 정찰병들 중에... \"대담한\" 녀석들이 이 세계의 불안정한 자원을 활용해 보려 한 것 같다. 수집하는 동안 괜한 사고는 일으키지 마라.', '', 68974),
(309015, 'koKR', '', '도마나르의 차원문 연결망을 교란하면 아제로스 침공의 기세가 한풀 꺾일 겁니다. 할 수 있는 만큼 놈들의 발을 묶어 주십시오.', 68974),
(309014, 'koKR', '역시나 또 다른 \"위협\"이 네 임무를 방해하는구나. 부수고, 말살하고, 마무리해라.', '', 68974),
(318546, 'koKR', '마법학자의 정원은 예로부터 배움의 터전이었습니다.\n\n분열이나 자존심 싸움 없이 생각을 나눌 수 있는 지식의 보루였지요.\n\n그런데 아무리 애써도, 돌아온 사람들을 보면 도저히...\n\n<이를 악문 채 침묵하는 마법학자>', '마법학자의 정원은 예로부터 배움의 터전이었습니다.\n\n분열이나 자존심 싸움 없이 생각을 나눌 수 있는 지식의 보루였지요.\n\n그런데 아무리 애써도, 돌아온 사람들을 보면 도저히...\n\n<이를 악문 채 침묵하는 마법학자>', 68974),
(318542, 'koKR', '<당신의 인기척에 한숨을 내쉬는 하이 엘프 마법학자>\n\n네놈이 왜 여기 있냐고 나무라지 말아 주시길... 또 차가운 시선이나 핀잔을 견뎌낼 자신이 없습니다.\n\n그저 마법을 배우고 새로운 주문을 연습하고 싶은 게 다입니다. 그게 그렇게 큰 욕심인가요?\n\n말다툼 때문에 돌아버릴 것 같습니다.', '<당신의 인기척에 한숨을 내쉬는 하이 엘프 마법학자>\n\n네놈이 왜 여기 있냐고 나무라지 말아 주시길... 또 차가운 시선이나 핀잔을 견뎌낼 자신이 없습니다.\n\n그저 마법을 배우고 새로운 주문을 연습하고 싶은 게 다입니다. 그게 그렇게 큰 욕심인가요?\n\n말다툼 때문에 돌아버릴 것 같습니다.', 68974),
(317974, 'koKR', '마법을 이해하고 통달하는 것. 그것이야말로 언제나 우리의 방식이었습니다. 마법학자의 방식 말입니다.\n\n부디 생각이 좀 더 트인 동족들이 나서서 우리가 왜 공허를 연구하는지 다른 이들에게도 알려 주면 좋겠군요.\n\n그렇다고 이 연구에 참여하고 싶지 않은 이들에게 추방을 들먹이며 위협할 생각은 없습니다.', '마법을 이해하고 통달하는 것. 그것이야말로 언제나 우리의 방식이었습니다. 마법학자의 방식 말입니다.\n\n부디 생각이 좀 더 트인 동족들이 나서서 우리가 왜 공허를 연구하는지 다른 이들에게도 알려 주면 좋겠군요.\n\n그렇다고 이 연구에 참여하고 싶지 않은 이들에게 추방을 들먹이며 위협할 생각은 없습니다.', 68974),
(317973, 'koKR', '벨드하린 님의 말에 따르면 최초의 지식 탐구자들은 선조들이 티리스팔에서 느낀 어둠의 존재를 조사했다고 합니다.\n\n정확히 뭘 발견했는지는 아무도 모릅니다. 다만 온전한 정신으로 돌아온 인원은 몇 되지 않았다고 하더군요.\n\n탐구자들이 뭘 봤고 뭘 찾아냈는지는 몰라도 다트리마께서 공허 마법을 금지할 이유로는 충분했던 모양입니다.\n\n엄브릭 님은 그 안을 들여다보셨을까요? 우리에게도 그럴 기회가 허락될까요?', '벨드하린 님의 말에 따르면 최초의 지식 탐구자들은 선조들이 티리스팔에서 느낀 어둠의 존재를 조사했다고 합니다.\n\n정확히 뭘 발견했는지는 아무도 모릅니다. 다만 온전한 정신으로 돌아온 인원은 몇 되지 않았다고 하더군요.\n\n탐구자들이 뭘 봤고 뭘 찾아냈는지는 몰라도 다트리마께서 공허 마법을 금지할 이유로는 충분했던 모양입니다.\n\n엄브릭 님은 그 안을 들여다보셨을까요? 우리에게도 그럴 기회가 허락될까요?', 68974),
(317972, 'koKR', '<당신의 인기척에 한숨을 내쉬는 마법학자>\n\n네가 왜 여기 있냐고 나무라지 말아 주시길... 또 차가운 시선이나 핀잔을 견뎌낼 자신이 없습니다.\n\n그저 마법을 배우고 새로운 주문을 연습하고 싶은 게 다입니다. 그게 그렇게 큰 욕심인가요?\n\n말다툼 때문에 돌아버릴 것 같습니다. 제가 이런 말을 할 정도라면 심각한 겁니다. 전 블랙홀까지 들여다본 적 있는 사람이라고요!', '<당신의 인기척에 한숨을 내쉬는 마법학자>\n\n네가 왜 여기 있냐고 나무라지 말아 주시길... 또 차가운 시선이나 핀잔을 견뎌낼 자신이 없습니다.\n\n그저 마법을 배우고 새로운 주문을 연습하고 싶은 게 다입니다. 그게 그렇게 큰 욕심인가요?\n\n말다툼 때문에 돌아버릴 것 같습니다. 제가 이런 말을 할 정도라면 심각한 겁니다. 전 블랙홀까지 들여다본 적 있는 사람이라고요!', 68974),
(317917, 'koKR', '솔직히 말하면 애초에 그럴 생각이었는지도 잘 모르겠습니다.\n\n그자가 의회와 우리 백성을 배신한 일은 역겨웠지만, 옴니움에 피해를 입히려 했을 것 같지는 않습니다.\n\n오랫동안 손도 못 대게 막혀 있던 금단의 지식 저장소를 굳이 파괴하려 들 리는 없으니까요.\n\n오히려 옴니움 전체를 훔쳐 가려 할 줄 알았습니다.\n\n그래서 일부나마 손에 넣는 것으로 만족한 걸지도 모르겠군요.', '', 68974),
(317750, 'koKR', '훌륭한 질문입니다! 어디 보자...\n\n우선 비전 마법 입자가 있습니다. 수천 년에 걸친 명가의 지식은 막 태동하던 우리 종족이 이 새로운 땅에서 번영할 토대가 되어 주었지요.\n\n화염을 비롯한 다른 원소의 마법 입자도 있습니다. 우리 세계를 이루는 자연의 근본이지요.\n\n빛 마법 입자에는 특이하게도 신성한 지식이 담겨 있습니다. 실버문의 대사제들이 그 지식에 크게 기여했지요.\n\n그리고 모두가 궁금해하는 금지된 마법 입자들도 있습니다...\n\n공허. 지옥. 강령술... 물론 그중 일부에 대한 제한은... 완화될지도 모르겠군요.\n\n<생각에 잠겨 미간을 찌푸리는 벨드하린>', '', 68974),
(317749, 'koKR', '옴니움 옆 명판을 보시길 권합니다. 다트리마 님의 뜻을 꽤 잘 정리해 두었거든요.\n\n간단히 말해, 이유는 여러 가지였고, 야망은 대담했으며, 목적은 영원노래 숲의 하늘처럼 선명했습니다.\n\n다트리마께서는 젊은 시절 많은 것을 보았습니다. 그리고 우리 세계의 마법이 가진 힘을 결코 외면하지 않았지요.', '', 68974),
(317744, 'koKR', '라이카네움에 오신 것을 환영합니다!\n\n여러분은 지금 끝없는 지식과 무한한 마법의 가능성 앞에 서 계십니다!\n\n물론 제가 말하는 건 선스트라이더 옴니움입니다. \n\n저는 그저 옴니움의 관리인일 뿐이지요. 젊은 마법학자 여러분의 질문에 답하고 마법과 학문의 여정에 길잡이가 되고자 이곳에 있습니다.\n\n궁금한 것이 있다면 언제든 물어보십시오.', '', 68974),
(317738, 'koKR', '마법 입자라는 이름은 누가 붙인 걸까요? 마나 입자라고 하면 안 되나? 잠깐, 그러면 마나 족쇄처럼 들리네요.\n\n옴니움 입자? 아니면 옴니... 쿨?\n\n다트리마시여, 내가 지금까지 잘못 발음하고 있었던 건가?', '마법 입자라는 이름은 누가 붙인 걸까요? 마나 입자라고 하면 안 되나? 잠깐, 그러면 마나 족쇄처럼 들리네요.\n\n옴니움 입자? 아니면 옴니... 쿨?\n\n다트리마시여, 내가 지금까지 잘못 발음하고 있었던 건가?', 68974),
(317722, 'koKR', '<잠시 눈을 가늘게 뜨는 롬매스>\n\n엄브릭과... 추종자들도 옴니움과 관련된 규정을 따라야 하오.\n\n렌도레이가 규칙을 지키지 못해서 공허의 흉물이 난무하는 촌극이 일어나는 꼴을 볼 순 없소.\n\n물론 엄브릭이 택한 길을 여전히 신뢰하진 않지만... 적어도 지금은 그자를 믿어 볼 여지가 있을지도 모르오.\n\n그자의 동족이 통달했다고 주장하는 공허 제어 능력이 있다면, 공허 마법 입자를 두고 조금 더... 학술적인 논의가 가능할 수도 있겠지.\n\n그렇다고 이 정원의 마법학자들에게 공허 마법을 새로운 교과 과정으로 제공할 생각은 없소!', '', 68974),
(317721, 'koKR', '옴니움에 담긴 지식은 마법학자에게만 연구가 허용되오. 그마저도 제한이 따르지.\n\n이러한 규칙과 규정은 여러 세대 전 다트리마께서 직접 세우셨소.\n\n덕분에 우린 새롭고 위험한 마법을 발견하고 체계화하면서도, 그 예측할 수 없는 힘으로부터 스스로를 지킬 수 있었소.\n\n다만 지옥 마법 입자에 접근하는 것조차 엄격히 금지되던 시절이 있긴 했소.\n\n세상이 이렇게 빨리 변할 줄이야...', '', 68974),
(317719, 'koKR', '<롬매스를 바라보며 미소 짓는 엄브릭>\n\n롬매스가 제 연구를... 좀처럼 인정하지 않긴 하지만, 옴니움은 언제나 안전장치와 규정 아래 철저히 보호되어 왔습니다.\n\n다행히도 온갖 마법을 아무나 들춰 볼 수 있는 마법 총서는 아니었지요.\n\n다르칸에게 접근 권한이 있었다면 무슨 일을 벌였을지, 생각만 해도 몸서리가 칩니다.\n\n그 규칙은 다트리마의 시대부터 이어져 왔습니다.\n\n다트리마가 처음 공허와 마주한 일, 고대의 전쟁에서 지옥 마법이 남긴 참상을 목격한 일. 바로 그 때문에 그런 마법을 금한 것이지요.\n\n그렇다 해도 논의의 여지는 있긴 합니다.', '', 68974),
(317717, 'koKR', '옴니움이 잠든 이래로 모두가 던진 질문입니다.\n\n정확히 무슨 일이 있었는지는 아무도 모릅니다. 우리가 아는 것은 발견 당시의 상태뿐이지요.\n\n정원이 함락됐을 때... 다르칸이 들이닥쳤을 때 저는 이곳에 없었습니다. 그 뒤의 참상은 봤지만요.\n\n옴니움이 그렇게 텅 빈 모습은 처음이었습니다. 마력의 빛 한 줄기, 마법 입자 하나 보이지 않았지요.\n\n황량하고 침묵하는 틀만 남아 있었습니다. 아무리 좋게 봐도... 불길했습니다.', '', 68974),
(317715, 'koKR', '옴니움을 발견했을 때, 잔해 속에는 텅 빈 틀만 남아 있었소. 마법 입자도, 룬의 빛도 없었지.\n\n다르칸의 학살이 남긴 오물 외에는 생기라고는 없는 물건처럼 보였소.\n\n마법 입자는 옴니움의 확장체로 만들어졌소. 마법 입자가 따로 떨어져 나갈 수 있는 부품이라고는 생각하지도 못했다오.\n\n유물이 깨어나 마법 입자들이 다시 나타났을 때, 중앙 행렬이 비어 있다는 사실을 알아차렸소.\n\n한 번도 본 적 없는 이상 현상이었소.\n\n마지막으로 사용된 마법 입자가 사라졌거나 파괴된 것이오. 아니, 이번 경우에는 도난당한 거라고 하는 게 맞겠지.', '', 68974),
(317714, 'koKR', '처음에는 그렇게 생각했소. \n\n다르칸이 의회를 학살하려고 정원에 왔다는 사실은 알고 있었다오. 벽과 옴니움 곳곳에 피비린내 나는 증거가 남아 있었지.\n\n그런데 다르칸의 서재와 거처를 급습했을 때 발견한 것은 더 어두운 마법에 대한 집착뿐이었소.\n\n훗날 엄브릭은 다르칸의 목적이 힘과 지식이었다고 지적했소. 그렇다면 옴니움을 훼손하는 일은 그자의... 야망과 어긋난단 말이오.', '', 68974),
(317713, 'koKR', '나도... 대답하기 어렵소.\n\n다만 옴니움을 되살리기 위해 할 수 있는 모든 일을 했소. 선스트라이더 열쇠 암호조차 아무 소용이 없었지.\n\n캘타스는... 깊은 슬픔에 잠겼소.\n\n우리 모두가 그랬듯, 너무 짧은 시간에 너무 많은 것을 잃었으니. \n\n왕자는 우리의 처지를, 우리 종족을 구할 답을 절박하게 찾고 있었소.\n\n옴니움 안의 지식이 도움이 되었을지도 모르오... 어쩌면 왕자를 이끌어 주었을지도 모르지.\n\n끝내 침묵한 옴니움 앞에서, 우리는 막다른 길에 몰리고 말았소.', '', 68974),
(316792, 'koKR', '선스트라이더 열쇠 암호를 인식하지 못했습니다. 거울 메아리 각인을 시작합니다.', '선스트라이더 열쇠 암호를 인식하지 못했습니다. 거울 메아리 각인을 시작합니다.', 68974),
(315312, 'koKR', '이 돈스타 첨탑은 다르칸 드라시르가 어린 시절을 보낸 집입니다. 참 고요하고 평온한 곳이었지요.\n\n실버문에서 추방된 뒤, 전 다르칸이 남긴 공허 연구의 흔적을 추적하다 이곳까지 오게 되었습니다.\n\n많은 연구를 비밀리에 진행했더군요. 이 탑 꼭대기에서 처음 텔로그러스로 향하는 균열을 열기도 했습니다.\n\n아직 파헤치지 못한 비밀이 남아 있으리라곤 꿈에도 몰랐건만...', '', 68974),
(314998, 'koKR', '마법학자도 아닌 외부인을 탐구자로 임명한 적은 없소. 다만 그대는 모험가로서의 기질이 남다르다 보니... 드물게 적임자인 경우지.\n\n탐구자가 되면, 엄브릭이나 나한테 연구 과제를 받게 될 거요.\n\n과제를 완료하면 보상으로 그대의 힘을 강화해 줄 강력한 룬 마법부여를 제공하리다.\n\n이 룬은 옴니움 장서에서 찾을 수 있소. 어느 룬에 힘을 불어넣을지는 그대가 정하시오.\n\n질문은 없소?', '', 68974),
(314900, 'koKR', '<고요한 옴니움을 올려다보는 롬매스>\n\n거의 다 됐소. 벨로비르 님의 열쇠 암호를 되찾았고, 그대와 엄브릭이 공허 마법 입자까지 회수했으니 남은 일은 하나요.\n\n$n, 지금 아니면 기회는 영영 없을 것이오. 준비됐소?', '', 68974),
(314899, 'koKR', '난 수년 동안 옴니움을 연구해 왔소. 전임 마법학자들처럼 옴니움에서 얻을 수 있는 건 모조리 터득했지. 룬과 주문, 영창까지 전부 말이외다.\n\n옴니움이 침묵에 잠긴 날은 여러모로 암울했소. 설마 부활하는 날이 오리라곤 꿈에도 몰랐지. 참 멀리도 왔구려.', '', 68974),
(314791, 'koKR', '벨로비르 님이 금고를 여는 방법을 적어 두셨구려... 이 설명서가 얼마나 오랫동안 날 기다렸을지.\n\n그분의 성격을 생각하면, 환영 복제 마법의 대가답게 무척 복잡하게 꾸며 놓았을 터.\n\n이제부터는 흩어져서 도전하는 편이 좋겠소. 난 위층 집무실로 올라가 까다로운 수호물을 맡으리다.\n\n그대는 내 환영 복제를 도와 바깥 지점 세 곳을 처리해 줄 수 있겠소?', '', 68974),
(314746, 'koKR', '다르칸이 언제부터 공허 마법 입자에 숨겨진 금단의 비밀을 좇았는지 문득 궁금해지는군요.\n\n처음 마법학자가 됐을 때, 총회가 엄격히 금지하는 마법 계통과 관련 마법 입자에 대한 강의를 들었습니다.\n\n다르칸은 달라란 시절부터 이미 공허에 끌리는 모습을 보였지요. 단순한 흥미 이상이었을지도 모릅니다.\n\n처음 라이카네움에 발을 들인 그날부터 공허 마법 입자를 탐냈던 걸까요?\n\n아니면 마법학자의 정원에서 동료들을 학살하던 그 마지막 순간, 과감해진 마음에 손을 뻗은 걸까요?', '', 68974),
(314744, 'koKR', '다르칸이 숨겨 놓은 비밀은 모두 찾아냈다고 생각했습니다. 그런데 오늘 일은 정말... 의외로군요.\n\n혹시 모르기도 하고... 무엇보다 롬매스 성격에 물어보지 않을 리 없으니, 또 무언가가 숨겨져 있지는 않은지 확인해 보겠습니다.\n\n제가 의식을 정리할 동안 롬매스를 도와 벨로비르의 열쇠 암호를 회수하십시오. 마법학자의 정원에서 다시 뵙겠습니다.', '', 68974),
(314678, 'koKR', '역시 짐작대로였군... $n 님도 느껴지십니까? 멀리서 울리는 서늘한 맥동을... 꼭 심장 소리가 먹먹하게 들리는 것 같네요.\n\n이 맥동이 우리가 찾던 걸지도 모릅니다. 바로 눈앞에 있으면서 보이지 않도록 숨겨져 있던 것이지요.\n\n알맞은 주문과 집중 장치만 갖추면, 공허의 힘으로 다르칸이 숨겨 놓은 비밀을 드러낼 수 있을 겁니다.\n\n용사님은 고정 장치를 연결하시고, 전 주문을 마무리하겠습니다.\n\n조심하십시오. 벌써 공허가 우리를 끌어당기고 있습니다.', '', 68974),
(310354, 'koKR', '벨로비르 님이 걸어 놓은 보호 마법을 해제해야 하오. 서재에서 용사와 합류하리다.', '', 68974),
(310059, 'koKR', '비전 마력이든 지옥 마력이든, 심지어 빛이나... 공허까지. 다트리마는 그 지식을 온전히 담아 둘 용도로 옴니움을 만들었습니다.', '', 68974),
(317919, 'koKR', '많은 사람이 같은 생각일 거요.\n\n평소라면 이런 질문은 얼마 전 은퇴를 접고 돌아온 지식의 수호자, 관리인 벨드하린에게 맡겼을 것이오.\n\n그렇지만 그대는 옴니움을 복구하는 데 공헌했으니, 이번만큼은 그 궁금증에 답해 주겠소.', '', 68974),
(317573, 'koKR', '이 세계... 이 모든 가능성... 이제 전부 내 것이다.', '', 68974),
(309931, 'koKR', '순찰대, 각오를 다져라! 저 괴물들에게 우리가 이곳의 수호자로 임명된 이유를 보여줘라!', '순찰대, 각오를 다져라! 저 괴물들에게 우리가 이곳의 수호자로 임명된 이유를 보여줘라!', 68974),
(307084, 'koKR', '아, $n 님.\n\n이 자리에서 이렇게 편안한 얼굴을 보니 반갑습니다. 지금은 저도 다시 도시에 받아들여졌지만, 미리 말씀드리죠... 롬매스는 또 자기 특기인 \"점멸 화살\"을 쏘아댈 겁니다. \n\n예전에 마법사 결투에서 경솔하게 도전한 자들에게 본보기를 보여주겠다며, 점멸 주문과 비전 화살을 하나로 합쳤죠. \n\n본인은 절대 인정 안 하겠지만, 투사체를 안 보이게 만드는 비결은 제가 알려준 겁니다.\n\n어쨌든 로르테마르의 허락을 받고 이 자리에 있는 만큼, 제 존재 하나만으로 다른 사람들이 얼마나 불편해하는지 지켜보는 재미가 쏠쏠하군요.', '', 68974),
(306595, 'koKR', '당장... 이 상황을 로르테마르 님께 알려야 합니다. 먼저 출발하십시오, 용사님.', '', 68974),
(304405, 'koKR', '전쟁과 혼란의 시기마다, 우리의 고대 수호정령들은 전장에서 굳건히 버텨줬습니다.\n\n다만 그들을 깨우려면 큰 노력이 필요하죠.\n\n장로 신록껍질 님의 전투 뜰지기들이 그대를 따를 거예요. 장로께서 적에게 내던질 만한 큰 바위나 돌덩이를 찾아야 합니다.\n\n지금은 던질 것이 없으면 일어날 생각조차 하지 않거든요.', '전쟁과 혼란의 시기마다, 우리의 고대 수호정령들은 전장에서 굳건히 버텨줬습니다.\n\n다만 그들을 깨우려면 큰 노력이 필요하죠.\n\n장로 신록껍질 님의 전투 뜰지기들이 그대를 따를 거예요. 장로께서 적에게 내던질 만한 큰 바위나 돌덩이를 찾아야 합니다.\n\n지금은 던질 것이 없으면 일어날 생각조차 하지 않거든요.', 68974),
(303273, 'koKR', '', '고대 수호정령은 적의 후방을 궤멸시킬 수 있는 강력한 공성 지원 능력을 갖췄지. \n\n호드라면 이들의 파괴적인 힘이 익숙할 거야.', 68974),
(300503, 'koKR', '', '그럴 리가요. 제가 직접 마법으로 울렌 총관에게 보냈습니다. 제가 자리에 없을 땐 책임 대행을 맡거든요. 수라마르에 무슨 일이 생긴 걸지도 모릅니다.', 68974),
(292933, 'koKR', '많은 수고가 들어간 물건이기도 하고, 가져갈 자격도 있으니까.', '', 68974),
(289958, 'koKR', '', '은빛 서약단이 실버문에 돌아가려고 합니다. 마지막으로요.', 68974);
