INSERT INTO `item_sparse_locale` (`ID`, `locale`, `Description_lang`, `Display3_lang`, `Display2_lang`, `Display1_lang`, `Display_lang`, `VerifiedBuild`) VALUES
(282426, 'koKR', '', '', '', '', '드레나이 동력 사슬', 68974),
(282425, 'koKR', '', '', '', '', '야수 학살자의 고리', 68974),
(262656, 'koKR', '각종 주황색 계열 하우징 염료 제작에 사용되는 안료입니다. 한밤 연금술 또는 한밤 주문각인으로 만듭니다. 경매장에서 거래할 수 있습니다.', '', '', '', '주황색 염료 안료', 68974),
(262655, 'koKR', '각종 붉은색 계열 하우징 염료 제작에 사용되는 안료입니다. 한밤 연금술 또는 한밤 주문각인으로 만듭니다. 경매장에서 거래할 수 있습니다.', '', '', '', '적색 염료 안료', 68974),
(262648, 'koKR', '각종 노란색 계열 하우징 염료 제작에 사용되는 안료입니다. 한밤 연금술 또는 한밤 주문각인으로 만듭니다. 경매장에서 거래할 수 있습니다.', '', '', '', '황색 염료 안료', 68974),
(262647, 'koKR', '각종 녹색 계열 하우징 염료 제작에 사용되는 안료입니다. 한밤 연금술 또는 한밤 주문각인으로 만듭니다. 경매장에서 거래할 수 있습니다.', '', '', '', '녹색 염료 안료', 68974),
(262643, 'koKR', '각종 푸른색 계열 하우징 염료 제작에 사용되는 안료입니다. 한밤 연금술 또는 한밤 주문각인으로 만듭니다. 경매장에서 거래할 수 있습니다.', '', '', '', '청색 염료 안료', 68974),
(262642, 'koKR', '각종 갈색 계열 하우징 염료 제작에 사용되는 안료입니다. 한밤 연금술 또는 한밤 주문각인으로 만듭니다. 경매장에서 거래할 수 있습니다.', '', '', '', '갈색 염료 안료', 68974),
(262639, 'koKR', '각종 검은색 계열 하우징 염료 제작에 사용되는 안료입니다. 한밤 연금술 또는 한밤 주문각인으로 만듭니다. 경매장에서 거래할 수 있습니다.', '', '', '', '흑색 염료 안료', 68974),
(262628, 'koKR', '각종 청록색 계열 하우징 염료 제작에 사용되는 안료입니다. 한밤 연금술 또는 한밤 주문각인으로 만듭니다. 경매장에서 거래할 수 있습니다.', '', '', '', '청록색 염료 안료', 68974),
(262625, 'koKR', '각종 보라색 계열 하우징 염료 제작에 사용되는 안료입니다. 한밤 연금술 또는 한밤 주문각인으로 만듭니다. 경매장에서 거래할 수 있습니다.', '', '', '', '자색 염료 안료', 68974),
(260947, 'koKR', '각종 흰색 계열 하우징 염료 제작에 사용되는 안료입니다. 한밤 연금술 또는 한밤 주문각인으로 만듭니다. 경매장에서 거래할 수 있습니다.', '', '', '', '백색 염료 안료', 68974),
(259154, 'koKR', '집에 있는 염색 가능한 하우징 장식에 빗방울 백일홍 빨간색 색상을 적용합니다. 한 번만 사용할 수 있습니다. 경매장에서 거래할 수 있습니다.', '', '', '', '빗방울 백일홍 빨간색 염료', 68974),
(259153, 'koKR', '집에 있는 염색 가능한 하우징 장식에 황혼 백합 회색 색상을 적용합니다. 한 번만 사용할 수 있습니다. 경매장에서 거래할 수 있습니다.', '', '', '', '황혼 백합 회색 염료', 68974),
(259152, 'koKR', '집에 있는 염색 가능한 하우징 장식에 동부 내륙지 히코리 색상을 적용합니다. 한 번만 사용할 수 있습니다. 경매장에서 거래할 수 있습니다.', '', '', '', '동부 내륙지 히코리 염료', 68974),
